"""The portable package (COORDINATION C1/C2): committed portable/, generated by
scripts/build-portable.py, never hand-edited.

Pinned contracts: freshness (portable/ == a fresh build, byte for byte, commit-stable),
same manifest name as the host (no double-run in Code), no top-level bin/, closure
complete (every ${CLAUDE_PLUGIN_ROOT}/${CLAUDE_SKILL_DIR} reference resolves inside
portable/ and never escapes via .. or absolute paths, no symlinks), the host→portable
file SET is pinned (every host skill + referenced hook file must be present),
PORTABLE-BUILD.json matches haiggoh-portable-build/1 (schema, per-file sha256 verified
against actual contents, non-empty components with the C3 vocabularies), and --zip emits
a deterministic upload zip with the manifest at the zip root WITHOUT touching portable/.
"""
import hashlib
import json
import re
import subprocess
import sys
import zipfile

import pytest
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).resolve().parent.parent
BUILD = ROOT / "scripts" / "build-portable.py"
PORTABLE = ROOT / "portable"

ADAPTATION_CLASSES = {"native-unchanged", "mechanical", "qualified-adapter",
                      "reduced-useful", "unsupported", "unknown"}
EVIDENCE_LEVELS = {"source-inspected", "fixture-tested", "runtime-qualified"}
KINDS = {"manifest", "skill", "hooks", "hook-script", "script", "data"}
REF_RE = re.compile(r"\$\{(CLAUDE_PLUGIN_ROOT|CLAUDE_SKILL_DIR)\}(?:/([^\s\"'\\]+))?")


def run_build(*args):
    return subprocess.run([sys.executable, str(BUILD), *args], capture_output=True,
                          text=True, cwd=ROOT, timeout=60)


def sha256(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def test_portable_dir_is_a_fresh_build():
    r = run_build("--check")
    assert r.returncode == 0, r.stdout + r.stderr


def test_portable_manifest_same_name_no_bin():
    m = json.loads((PORTABLE / ".claude-plugin" / "plugin.json").read_text(encoding="utf-8"))
    host = json.loads((ROOT / ".claude-plugin" / "plugin.json").read_text(encoding="utf-8"))
    assert m["name"] == host["name"] == "watch-your-step"
    assert m["version"] == host["version"]
    assert not (PORTABLE / "bin").exists(), "top-level bin/ blocks Chat/Cowork installs"


def test_host_to_portable_file_set_is_pinned():
    """Every host skill and every hook-referenced script must exist in portable/, with the
    CLI moved bin/ -> scripts/ (byte-identical) and rules/rules.json at the portable root
    (the CLI resolves it via dirname(dirname(__file__)))."""
    for s in sorted(ROOT.glob("skills/*/SKILL.md")):
        assert (PORTABLE / s.relative_to(ROOT)).is_file(), f"host skill missing: {s}"
    hooks = json.loads((PORTABLE / "hooks" / "hooks.json").read_text(encoding="utf-8"))
    refs = re.findall(r"\$\{?CLAUDE_PLUGIN_ROOT\}?/scripts/([A-Za-z0-9_.-]+)",
                      json.dumps(hooks))
    assert refs, "hooks.json must reference the script via scripts/"
    for rel in refs:
        assert (PORTABLE / "scripts" / rel).is_file(), f"hook script missing: {rel}"
        assert (PORTABLE / "scripts" / rel).read_bytes() == (ROOT / "bin" / rel).read_bytes(), rel
    assert (PORTABLE / "rules" / "rules.json").read_bytes() == (ROOT / "rules" / "rules.json").read_bytes()


def test_portable_closure_complete_and_no_escapes():
    assert PORTABLE.is_dir(), "portable/ must exist (run scripts/build-portable.py)"
    for p in sorted(PORTABLE.rglob("*")):
        assert not p.is_symlink(), f"symlink in portable package: {p}"
    # braceless $VAR/... references escape both the ${...} scan and a naive grep — catch them
    braceless = re.compile(r"(?<!\$\{)(?<!\w)\$(?:CLAUDE_PLUGIN_ROOT|CLAUDE_SKILL_DIR)/([^\s\"'\\)]+)")
    for p in sorted(PORTABLE.rglob("*")):
        if not p.is_file() or p.suffix not in (".json", ".sh", ".py", ".md") \
                or p.name == "PORTABLE-BUILD.json":  # its notes describe the ${...} contract
            continue
        text = p.read_text(encoding="utf-8", errors="replace")
        if p.suffix != ".md":
            # executable code only: a literal ../ there is an escape. .json data (rule fix
            # text like ../.wt/<name>) and .md guidance may contain ../ — checked via refs.
            # In .py files, strings/comments are stripped with tokenize first, so a ../
            # inside a docstring/usage example (e.g. "git worktree add ... ../.wt/<name>")
            # is not flagged; only LIVE code escapes.
            if p.suffix == ".py":
                # AST: flag ../ only in CALL ARGUMENTS (a path passed to open()/os.path/...).
                # Plain string constants (rule guidance text like "git worktree add ... ../.wt/<name>")
                # and docstrings are exempt — they are data, not resolved paths.
                import ast as _ast
                tree = _ast.parse(text)
                for n in _ast.walk(tree):
                    if isinstance(n, _ast.Call):
                        for arg in list(n.args) + [k.value for k in n.keywords]:
                            if isinstance(arg, _ast.Constant) and isinstance(arg.value, str) \
                                    and "../" in arg.value:
                                assert False, \
                                    f"live-code ../ escape in {p.relative_to(PORTABLE)}: {arg.value!r}"
            elif p.suffix == ".sh":
                assert re.search(r"(?<!\.)\.\./", text) is None, \
                    f"literal ../ escape in {p.relative_to(PORTABLE)}"
        for m in REF_RE.finditer(text):
            rel = m.group(2)  # group(1) is the variable name; group(2) is the path
            if rel is None:
                continue  # bare ${VAR} — the root itself
            parts = PurePosixPath(rel).parts
            assert ".." not in parts and not PurePosixPath(rel).is_absolute(), \
                f"{p.relative_to(PORTABLE)} references escaping path {rel}"
            assert (PORTABLE / rel).exists(), \
                f"{p.relative_to(PORTABLE)} references {rel}, missing in portable/"
        for m in braceless.finditer(text):
            rel = m.group(1)
            assert (PORTABLE / rel).exists(), \
                f"{p.relative_to(PORTABLE)} braceless ref {rel}, missing in portable/"


def test_portable_build_json_matches_c2_schema():
    d = json.loads((PORTABLE / "PORTABLE-BUILD.json").read_text(encoding="utf-8"))
    assert d["schema"] == "haiggoh-portable-build/1"
    for k in ("source_repo", "source_commit", "builder", "builder_version",
              "transform_version", "files", "components"):
        assert k in d, f"PORTABLE-BUILD.json missing {k}"
    assert re.fullmatch(r"[0-9a-f]{40,64}", d["source_commit"])
    assert "/" in d["source_repo"] and not d["source_repo"].endswith("/"), d["source_repo"]
    expected = {str(p.relative_to(PORTABLE)).replace("\\", "/") for p in PORTABLE.rglob("*")
                if p.is_file() and p.name != "PORTABLE-BUILD.json"}
    assert set(d["files"]) == expected, "files map must cover every portable file"
    for rel, h in d["files"].items():
        assert re.fullmatch(r"[0-9a-f]{64}", h), rel
        assert sha256(PORTABLE / rel) == h, f"hash mismatch for {rel}"  # verified, not just format
    assert d["components"], "components must be non-empty"
    for c in d["components"]:
        assert {"path", "kind", "adaptation_class", "evidence_level", "surfaces"} <= set(c)
        assert c["kind"] in KINDS, c
        assert c["adaptation_class"] in ADAPTATION_CLASSES, c
        assert c["evidence_level"] in EVIDENCE_LEVELS, c
        assert set(c["surfaces"]) == {"chat", "cowork", "code"}, c
        assert all(isinstance(v, bool) for v in c["surfaces"].values()), c
        assert (PORTABLE / c["path"]).exists(), c["path"]


def test_zip_is_deterministic_manifest_at_root_and_side_effect_free(tmp_path):
    before = {str(p.relative_to(PORTABLE)): sha256(p) for p in PORTABLE.rglob("*") if p.is_file()}
    r1 = run_build("--zip", "--out", str(tmp_path / "a"))
    r2 = run_build("--zip", "--out", str(tmp_path / "b"))
    assert r1.returncode == 0 and r2.returncode == 0, (r1.stdout + r1.stderr, r2.stdout + r2.stderr)
    za, zb = tmp_path / "a" / "watch-your-step-portable.zip", tmp_path / "b" / "watch-your-step-portable.zip"
    assert za.read_bytes() == zb.read_bytes(), "zip must be byte-deterministic across builds"
    names = zipfile.ZipFile(za).namelist()
    assert ".claude-plugin/plugin.json" in names, names
    assert not any(n.startswith("portable/") or "\\" in n for n in names), "zip root must be the package root"
    assert sorted(names) == sorted(before) + [], names  # every portable file, exactly
    after = {str(p.relative_to(PORTABLE)): sha256(p) for p in PORTABLE.rglob("*") if p.is_file()}
    assert before == after, "--zip must not mutate the committed portable/"


def test_all_skill_md_strict_parse_host_and_portable():
    """Strict-YAML frontmatter over skills/ AND portable/skills/ (the 2.1.x lesson: a plain
    scalar containing ': ' fails strict parsers like the claude.ai upload validation)."""
    yaml = pytest.importorskip("yaml")
    import re as _re
    files = sorted(ROOT.glob("skills/*/SKILL.md")) + sorted(PORTABLE.glob("skills/*/SKILL.md"))
    assert files
    for f in files:
        m = _re.match(r"\A---\r?\n(.*?)\r?\n---\r?\n", f.read_text(encoding="utf-8"), _re.S)
        assert m, f"{f}: no frontmatter block"
        d = yaml.safe_load(m.group(1))
        assert isinstance(d, dict) and d.get("name") and d.get("description"), f


def test_portable_cli_emits_primer_from_portable_root():
    """The functional proof advertised in the commit/CHANGELOG: the portable CLI runs from
    the portable root and finds its rules/ there (the SessionStart primer is emitted)."""
    cli = (PORTABLE / "scripts" / "watch-your-step.py").resolve()
    r = subprocess.run([sys.executable, str(cli), "primer"],
                       capture_output=True, text=True, cwd=ROOT, timeout=15)
    assert r.returncode == 0, r.stderr
    payload = json.loads(r.stdout)  # the hook envelope; the primer is inside
    primer = payload["hookSpecificOutput"]["additionalContext"]
    assert "watch-your-step session primer" in primer and len(primer.splitlines()) > 5, primer[:200]
